import{_ as a,H as t,f as r,i as l}from"./chunks/framework.BH2BK_3i.js";const d=JSON.parse('{"title":"加餐2 | 设置你的学习“母题”：如何选择阅读材料？","description":"","frontmatter":{},"headers":[{"level":2,"title":"选择学习的“母题”","slug":"选择学习的-母题","link":"#选择学习的-母题","children":[]},{"level":2,"title":"Survey和书籍是最好的起点","slug":"survey和书籍是最好的起点","link":"#survey和书籍是最好的起点","children":[]},{"level":2,"title":"不盲目追新，从经典开始","slug":"不盲目追新-从经典开始","link":"#不盲目追新-从经典开始","children":[]},{"level":2,"title":"寻找相关论文，丰富问题视角","slug":"寻找相关论文-丰富问题视角","link":"#寻找相关论文-丰富问题视角","children":[]},{"level":2,"title":"从工业界和学术界汲取养料","slug":"从工业界和学术界汲取养料","link":"#从工业界和学术界汲取养料","children":[]},{"level":2,"title":"小结","slug":"小结","link":"#小结","children":[]},{"level":2,"title":"推荐阅读","slug":"推荐阅读","link":"#推荐阅读","children":[]},{"level":2,"title":"思考题","slug":"思考题","link":"#思考题","children":[]}],"relativePath":"大数据经典论文解读/加餐2-设置你的学习“母题”：如何选择阅读材料？.md","filePath":"大数据经典论文解读/加餐2-设置你的学习“母题”：如何选择阅读材料？.md","lastUpdated":1779819465000}'),i={name:"大数据经典论文解读/加餐2-设置你的学习“母题”：如何选择阅读材料？.md"};function n(o,e,s,p,h,c){return t(),r("div",null,[...e[0]||(e[0]=[l('<h1 id="加餐2-设置你的学习-母题-如何选择阅读材料" tabindex="-1">加餐2 | 设置你的学习“母题”：如何选择阅读材料？ <a class="header-anchor" href="#加餐2-设置你的学习-母题-如何选择阅读材料" aria-label="Permalink to &quot;加餐2 | 设置你的学习“母题”：如何选择阅读材料？&quot;">​</a></h1><p>你好，我是徐文浩。到目前为止，我们已经一起学习了大量的论文。而在之前，我也在课程里和你聊过阅读一篇论文的办法。不过，计算机领域的论文浩如烟海，而且每年也不断地有大量的新论文出现。那么， <strong>作为一个工程师，我们该选择哪些论文去研究学习呢？</strong> 有不少同学，也在课程刚开始的时候，提出了这样的疑问。</p><p>那么，今天我们就通过加餐环节，来聊一聊这个问题。</p><p>我们这一讲的目标，更多针对的是之前没有太多通过研读论文，来拓展自己在技术领域的“宽度”的同学们。如果你已经深入研究某一个领域，并且经常需要精读最新的论文来了解学术界的进展，那么这一讲的内容就并不是针对你的学习场景的。</p><h2 id="选择学习的-母题" tabindex="-1">选择学习的“母题” <a class="header-anchor" href="#选择学习的-母题" aria-label="Permalink to &quot;选择学习的“母题”&quot;">​</a></h2><p>我们之前说过，作为一个工程师，想要通过论文来学习，大部分情况下的目标往往不是“深”，而是“广”。我们想要的是，能够把领域里的最新进展和自己的工作结合起来。所以，在寻找具体要学习什么论文之前，我们先要确定自己学习研究的“母题”。</p><p>“母题”的选择，一方面要和你的工作结合起来，否则即使你花时间、花精力把论文搞懂了，但是没有实践应用的机会，往往过不了多久就忘了。另一方面，又需要有一定的宽泛性，否则往往只是在一些实现细节里面打转，起不到开阔眼界、把各个领域联系起来的作用。</p><p>那么，最合理的“母题”的范围，最好是一个你需要解决的“核心问题”，而不是某一个特定的关键字或者某一门特定的课程。比如，我们这个课程里选择的论文，就是围绕着“大数据”这个母题的。 <strong>更准确地来说，我们所有选择的论文，都是围绕着“工业界的大数据系统”这个母题的。</strong></p><p>因为，我自己过去所需要解决的问题，就是如何在工程上能够及时处理海量的互联网数据。所以，无论是MapReduce这样的大数据批处理系统、Bigtable这样的分布式KV数据库，还是MillWheel这样的近实时的流式数据处理系统，都会为我所要解决的问题提供价值。</p><p>而在选择论文的时候，我们选择的每一篇论文，都对应着一个实际在工业界中得到长期应用的系统。</p><p>如果不围绕我们关注的问题，那我们可以挑选的论文范围一下子会变得非常大。比如，光一个分布式共识问题，我们就有Paxos、Multi-Paxos、ZAB、Raft、Viewstamped Replication等问题可以去讲。但是，对于实际的大数据系统应用来说，对Paxos有认识，能理解掌握Raft算法，对于大数据系统层面的开发，也就足够了。</p><p>如果你漫无边际地去找所有和“大数据”这个关键字沾边的论文，那很有可能读了半天，什么具体问题都解决不了。这样，你在学习的过程中会缺少“正反馈”，很难坚持下去。</p><p>同时，我也不建议你把你关注的“母题”设置得过于狭隘。在“大数据”领域，你当然可以只去关注“分布式KV数据库”这样一个细分的领域。光这个领域，从Bigtable开始，你就有HBase、Cassandra、Dynamo、Voldermort，以及许许多多别的论文和系统可以研究学习。</p><p>如果你是专门做分布式KV数据库的研发，这些论文你自然需要深入阅读。但是如果只局限在这些内容上，会让你错过整个大领域的发展，无论是Google Spanner带来的强一致的分布式关系数据库，还是这两年随着Dataflow模型的完善，开始逐步站上历史舞台的实时数据库，你都很难仅仅通过分布式KV数据库的论文了解到。</p><h2 id="survey和书籍是最好的起点" tabindex="-1">Survey和书籍是最好的起点 <a class="header-anchor" href="#survey和书籍是最好的起点" aria-label="Permalink to &quot;Survey和书籍是最好的起点&quot;">​</a></h2><p>在选定了你要学习的“母题”之后，我给你第一步的建议是，先别着急找一篇某个系统、算法的具体论文来读，而是先从课程、书籍、Survey入手，对整个领域有一个概括性的认识。</p><p>我之前就说过，“论文”因为它本身是发表给业内的其他同行审阅的，往往会“微言大义”，有很多前置知识往往是一笔带过的。在这种情况下，你直接拿一篇论文来“啃”，往往会因为缺少背景知识，让整个学习过程变得效率低下。</p><p>所以，你最好是能够找到自己所关注领域的“历史脉络”，而这个历史脉络，往往可以在Survey性质的论文、经典的课程和书籍中找到。比如，在我们的这个大数据论文的课程里，我就推荐过《Streaming Systems》《数据密集型系统设计》，以及《Big Data：A Survey》这篇论文。</p><p>然后，在深入阅读某一篇论文之前，你可以先快速浏览一下这些阅读材料，确保自己对整个大数据领域有一个整体性的认识，这会大大节约你后续学习的时间。</p><p>一方面，这些材料往往更成体系，并且对很多知识点都给出了具体的解释、分类和对比，这样你在后续阅读论文的时候，至少不会遇到太多让你有陌生感的名词。另一方面，在遇到论文里的有些内容，你觉得似是而非、不太理解的时候，你也可以回到这些书籍和课程，做一些对照。</p><p>同时，在这些书籍和Survey里，还会给出大量引用的论文。这也就给了你一个按图索骥，寻找论文去学习研究的清单。你只需要在 <a href="https://scholar.google.com" target="_blank" rel="noreferrer">谷歌学术搜索</a> 里输入论文的名称，很容易就能找到论文的电子版。</p><h2 id="不盲目追新-从经典开始" tabindex="-1">不盲目追新，从经典开始 <a class="header-anchor" href="#不盲目追新-从经典开始" aria-label="Permalink to &quot;不盲目追新，从经典开始&quot;">​</a></h2><p>不过，那么多论文，我们应该从哪些论文开始读呢？</p><p>我们在学习技术的时候，往往会选择尽量去学习最新的技术。比如，现在做大数据分析，你大概率会学习使用Spark SQL，而不是原始的Java MapReduce。</p><p>不过，在阅读论文的时候，我给你的建议恰恰相反。 <strong>我建议你尽量去读经典的、引用数量高的论文。然后，随着技术变迁的脉络，逐渐往后读到新的论文。</strong></p><p>这是因为，在学习具体要使用的技术的时候，我们的目的是立刻用起来。“老”的技术往往因为有着种种的不足和缺陷，所以自然没有必要花时间去学习研究。但是，在研读论文的时候，我们的目的是搞清楚具体的技术原理和解决问题的思路。这个时候，经典论文的价值就体现出来了。</p><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/474158/c0d19450345edf4a789672c6ed5c3275.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/474158/c0d19450345edf4a789672c6ed5c3275.png" alt="图片"></a></p><p>在谷歌学术搜索里，你可以直接看到论文的引用数量和发表时间。一般来说，我建议你选取最近5~15年，引用数量至少在100以上的论文。如果是同一个主题下的论文有很多都满足这个筛选条件，那么优先选择时间早、引用数多的论文。</p><p>发表5年以上，引用数众多的论文，往往已经经过了时间的检验，说明它的确在这个领域里解决清楚了某一个重要的问题，或者至少是整个领域发展的一个里程碑。而超出15年以上的论文，时间就会有些过于久远了，往往其中的知识可以直接在教科书里就能找到，你不一定需要选择去读论文原文。</p><h2 id="寻找相关论文-丰富问题视角" tabindex="-1">寻找相关论文，丰富问题视角 <a class="header-anchor" href="#寻找相关论文-丰富问题视角" aria-label="Permalink to &quot;寻找相关论文，丰富问题视角&quot;">​</a></h2><p>在找到对应的经典论文并研读完毕之后，你还可以进一步地阅读从这篇论文延伸出来的其他论文。一般来说，你会遇到这样几种场景：</p><ul><li>第一种，是论文需要大量的前置知识。比如我们之前看过的Spanner论文里，就会引用到Bigtable、Paxos、Chubby等相关内容。这些对应的论文，在你阅读论文最后的参考文献部分，往往都能找到。你可以针对其中你并不理解的主题，进一步深入了解下去。</li><li>第二种，和论文相同的主题下，有各色各样的其他解决方案。比如我们之前学习过的流式处理系统，除了我们看过的S4、Storm、MillWheel和Dataflow模型之外，还有Heron、Naiad、Samza、Flink等一系列其他的系统。这个，你就可以通过谷歌学术搜索里的相关文章，找到大量高引用的相关论文。</li></ul><p><a class="image-link" href="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/474158/ec8604fa9c381238yyf4f00ec8cb9418.png" target="_blank" rel="noopener" title="点击查看原图"><img src="https://raw.githubusercontent.com/qiangshuifish/note-website/note-website/%E5%A4%A7%E6%95%B0%E6%8D%AE%E7%BB%8F%E5%85%B8%E8%AE%BA%E6%96%87%E8%A7%A3%E8%AF%BB/images/474158/ec8604fa9c381238yyf4f00ec8cb9418.png" alt="图片"></a></p><p>对于这两类论文，我建议你先尽量去读一下第一种。因为这些论文，会对于你掌握理解已经读过的论文更有帮助。而对于第二种论文，我建议你可以做一下泛读，有个了解，或者也可以先收藏起来。这些论文，往往在你对整个领域的全貌有了一定的了解之后，回过头来读，会更高效。</p><h2 id="从工业界和学术界汲取养料" tabindex="-1">从工业界和学术界汲取养料 <a class="header-anchor" href="#从工业界和学术界汲取养料" aria-label="Permalink to &quot;从工业界和学术界汲取养料&quot;">​</a></h2><p>除了通过一篇论文衍生开来寻找论文，还有一个好去处，就是各大公司研究院的官方网站。无论是Google还是Facebook，你都可以在他们的网站上，找到以他们公司名义发表的论文。而且，这些论文，都已经分门别类，按照研究领域和发表时间划分好了。</p><p>对于MapReduce这些论文，你可以在 <a href="https://research.google/pubs/?area=distributed-systems-and-parallel-computing" target="_blank" rel="noreferrer">research.google.com</a> 里的“分布式系统与并行计算”（Distributed Systems and Parallel Computing）里面找到；对于Hive这样的论文，你也可以在 <a href="https://research.facebook.com/publications" target="_blank" rel="noreferrer">research.facebook.com</a> 里的数据库（Databases）这个领域里面找到。</p><p>当然，除了Google、Facebook、微软这样的巨头，很多互联网公司并没有一个专门的研究团队。不过，大部分公司也都会有工程团队的官方博客，比如Twitter工程团队的 <a href="https://blog.twitter.com/engineering/en_us" target="_blank" rel="noreferrer">官方博客</a>，也是一个值得追踪的阅读材料。</p><p>前面这些，是你从工业界里能够找到的阅读材料。还有一个办法，就是去关注一下学术界的各个会议。</p><p>就以这门课程关注的大数据领域为例，你可以去看看像VLDB这样每年召开的学术会议发表的论文。我们之前讲解过的Google的Dataflow的流式计算模型，就是在 <a href="https://www.vldb.org/2015/industrial-papers.html" target="_blank" rel="noreferrer">2015年的VLDB会议</a> 上发表的。如果比较经典的论文你都已经读过了，你也对关注的整个领域已经有比较全面的了解了，那么追踪最新会议发表的论文就更适合你了。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><p>好了，相信通过Survey和书籍、论文的引用和相关论文，以及追踪各大公司研究团队的官方网站和学术会议，你不会缺少可以阅读的论文了。而通过论文发表的时间和引用数，你也可以很容易地挑选出一些经典论文先去阅读。</p><p>希望我今天介绍的这些方法和渠道，能够帮助你快速找出一些值得阅读的论文。</p><h2 id="推荐阅读" tabindex="-1">推荐阅读 <a class="header-anchor" href="#推荐阅读" aria-label="Permalink to &quot;推荐阅读&quot;">​</a></h2><p>今天的推荐阅读，我要给你推荐的不是一篇文章，而是一个软件。大部分论文你下载下来都是PDF的文件，我一般都会使用 <a href="https://www.mendeley.com" target="_blank" rel="noreferrer">Mendeley</a> 这个软件，来收集和管理所有我要阅读的论文。并且你也可以直接使用它在论文里面做笔记，网上也有详细的 <a href="https://zhuanlan.zhihu.com/p/65992720" target="_blank" rel="noreferrer">使用教程</a>。如果你未来会把阅读论文，作为你学习成长中不可或缺的一步的话，那么你可以尽早把它用起来。</p><h2 id="思考题" tabindex="-1">思考题 <a class="header-anchor" href="#思考题" aria-label="Permalink to &quot;思考题&quot;">​</a></h2><p>最后，给你留一道小作业。根据今天我介绍的这些渠道，你能不能围绕着大数据这个主题，在我们课程的范围之外，找到一篇你觉得最值得阅读的论文推荐给大家呢？</p><p>欢迎留言说说你的方法，也欢迎把课程分享给更多的朋友。</p>',48)])])}const g=a(i,[["render",n]]);export{d as __pageData,g as default};
